-- 炼器、真正的护器、递增妖兽遭遇率。由 scripts/generate-forging-content.js 确定性生成。

ALTER TABLE equipment ADD COLUMN IF NOT EXISTS recipe JSONB;
ALTER TABLE equipment ADD COLUMN IF NOT EXISTS craft_time_s INT NOT NULL DEFAULT 180;
ALTER TABLE equipment ADD COLUMN IF NOT EXISTS recipe_source_description TEXT;

CREATE TABLE IF NOT EXISTS character_equipment_recipes (
  id SERIAL PRIMARY KEY,
  character_id INT NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
  equipment_id INT NOT NULL REFERENCES equipment(id) ON DELETE CASCADE,
  obtained_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (character_id, equipment_id)
);
CREATE TABLE IF NOT EXISTS equipment_craft_queue (
  id SERIAL PRIMARY KEY,
  character_id INT NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
  equipment_id INT NOT NULL REFERENCES equipment(id),
  quantity INT NOT NULL DEFAULT 1 CHECK (quantity BETWEEN 1 AND 5),
  started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  finish_at TIMESTAMPTZ NOT NULL,
  is_collected BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE INDEX IF NOT EXISTS idx_equipment_craft_queue ON equipment_craft_queue(character_id, is_collected, finish_at);

