INSERT INTO area_material_drops (area_code,item_id,weight,min_quantity,max_quantity)
SELECT a.code, i.id, CASE WHEN i.code LIKE 'forge_core_%' THEN 9000 WHEN i.code LIKE 'forge_hide_%' THEN 14000 ELSE 18000 END, 1, CASE WHEN a.min_realm_order < 17 THEN 3 WHEN a.min_realm_order < 33 THEN 2 ELSE 1 END
FROM areas a JOIN items i ON i.type='material' AND i.major_realm=a.major_realm AND i.code LIKE 'forge_%'
ON CONFLICT (area_code,item_id) DO UPDATE SET weight=EXCLUDED.weight,min_quantity=EXCLUDED.min_quantity,max_quantity=EXCLUDED.max_quantity;

UPDATE equipment SET slot='weapon', combat_role='attack', attack_bonus=GREATEST(1,attack_bonus+defense_bonus), defense_bonus=defense_bonus/4, hp_bonus=hp_bonus/4, source_description=major_realm || '对应区域可得器谱和炼材；成品仅以极低概率直接掉落。';
