UPDATE area_drop_rules SET base_rate=0.18, pity_after=6, description='器物机缘：命中后优先获得未收录器谱，另有5%机会直接获得成品。' WHERE category='equipment';

ALTER TABLE areas ADD COLUMN IF NOT EXISTS encounter_base_rate NUMERIC(6,5) NOT NULL DEFAULT 0.20;
ALTER TABLE areas ADD COLUMN IF NOT EXISTS encounter_pity_after SMALLINT NOT NULL DEFAULT 5;
UPDATE areas SET encounter_base_rate=CASE WHEN min_realm_order<9 THEN 0.18 WHEN min_realm_order<25 THEN 0.22 WHEN min_realm_order<37 THEN 0.26 ELSE 0.30 END, encounter_pity_after=5;
CREATE TABLE IF NOT EXISTS character_encounter_pity (
  character_id INT NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
  area_code VARCHAR(50) NOT NULL REFERENCES areas(code) ON DELETE CASCADE,
  misses SMALLINT NOT NULL DEFAULT 0 CHECK(misses BETWEEN 0 AND 4),
  PRIMARY KEY(character_id,area_code)
);

INSERT INTO character_equipment_recipes(character_id,equipment_id) SELECT c.id,e.id FROM characters c JOIN equipment e ON e.code IN ('weapon_mortal_01','armor_mortal_01') ON CONFLICT DO NOTHING;
